import{_ as e,a}from"./chunks/tasks-eisenhower-view.Cm7aI_Bm.js";import{_ as s,H as n,f as r,i as o}from"./chunks/framework.CSxcEb-0.js";const i="/tempad/docs/screenshots/task-layouts.gif",d="/tempad/docs/screenshots/tasks-kanban-view.png",l="/tempad/docs/screenshots/eisenhower-drag.gif",w=JSON.parse('{"title":"Tasks","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tasks.md","filePath":"guide/tasks.md"}'),g={name:"guide/tasks.md"};function h(u,t,c,p,m,k){return n(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h1><p>The <strong>Tasks</strong> view is where you create and triage work before it lands on the calendar.</p><p><img src="'+e+'" alt="Tasks list view"></p><h2 id="layouts" tabindex="-1">Layouts <a class="header-anchor" href="#layouts" aria-label="Permalink to &quot;Layouts&quot;">​</a></h2><p>Switch layouts with the <strong>List</strong>, <strong>Board</strong>, and <strong>Matrix</strong> tabs in the Tasks toolbar:</p><p><img src="'+i+'" alt="Switching task layouts"></p><h3 id="list-mode" tabindex="-1">List mode <a class="header-anchor" href="#list-mode" aria-label="Permalink to &quot;List mode&quot;">​</a></h3><p>Best for fast editing: search, complete tasks, and review metadata (due date, duration, list, priority, Eisenhower quadrant badge).</p><h3 id="kanban-mode" tabindex="-1">Kanban mode <a class="header-anchor" href="#kanban-mode" aria-label="Permalink to &quot;Kanban mode&quot;">​</a></h3><p>Columns follow your <strong>lists</strong>. Drag cards between columns to change list assignment or stage-style workflow.</p><p><img src="'+d+'" alt="Tasks Kanban view"></p><h3 id="eisenhower-matrix" tabindex="-1">Eisenhower matrix <a class="header-anchor" href="#eisenhower-matrix" aria-label="Permalink to &quot;Eisenhower matrix&quot;">​</a></h3><p>Sorts tasks into four quadrants by <strong>urgency</strong> and <strong>importance</strong> so you can decide what to do first, schedule, delegate, or defer.</p><p><img src="'+a+'" alt="Eisenhower matrix"></p><table tabindex="0"><thead><tr><th>Quadrant</th><th>Label</th><th>Typical use</th></tr></thead><tbody><tr><td>Q1</td><td><strong>Do first</strong></td><td>Urgent and important — deadlines, crises</td></tr><tr><td>Q2</td><td><strong>Schedule</strong></td><td>Important, not urgent — goals and planning</td></tr><tr><td>Q3</td><td><strong>Delegate</strong></td><td>Urgent, not important — interruptions, quick asks</td></tr><tr><td>Q4</td><td><strong>Later</strong></td><td>Neither urgent nor important — batch or drop</td></tr></tbody></table><p><strong>How placement works</strong></p><ul><li>Turn on <strong>Use task priorities</strong> in Settings to treat <strong>ASAP</strong> as always urgent/important (Q1).</li><li>Mark <strong>Important</strong> or <strong>Urgent</strong> on a task in the editor for explicit matrix placement.</li><li>Without flags, <strong>due date</strong> drives urgency (due today or within the next couple of days counts as urgent).</li><li>Drag cards between quadrants to update importance/urgency flags.</li></ul><p><img src="'+l+'" alt="Dragging a task between Eisenhower quadrants"></p><p><strong>Settings</strong></p><ul><li><strong>Show inbox tasks in Eisenhower matrix</strong> — include inbox/backlog items in the matrix (off by default).</li><li>List filters still apply: use sidebar chips to focus on Work, Personal, or Inbox.</li></ul><p>New users get sample tasks in each quadrant when the app seeds demo data on first load.</p><h2 id="scheduling-mode-task-editor" tabindex="-1">Scheduling mode (task editor) <a class="header-anchor" href="#scheduling-mode-task-editor" aria-label="Permalink to &quot;Scheduling mode (task editor)&quot;">​</a></h2><p>Use the <strong>Scheduling</strong> dropdown when editing a task:</p><ul><li><strong>Auto-schedule</strong> — TemPad finds time on your calendar within scheduling hours.</li><li><strong>Inbox</strong> — capture work for triage; it stays off the calendar until you promote it (switch mode, or set a due date / ASAP / Important+Urgent so it graduates on save).</li><li><strong>Fixed times</strong> — you set start and end; TemPad does not auto-place the task.</li></ul><p>Inbox and auto-schedule cannot apply at once. New tasks created while the Inbox filter is active start in <strong>Inbox</strong>.</p><h2 id="creating-tasks" tabindex="-1">Creating tasks <a class="header-anchor" href="#creating-tasks" aria-label="Permalink to &quot;Creating tasks&quot;">​</a></h2><p>When adding a task, set at minimum:</p><ul><li><strong>Title</strong></li><li><strong>List</strong> (or default list from Settings)</li><li><strong>Due date</strong> — required for scheduling placement</li><li><strong>Duration</strong> — minutes of work the scheduler should allocate</li></ul><p>Optional: priority (if enabled in Settings), <strong>Important</strong> / <strong>Urgent</strong> for Eisenhower, dependencies, splittable flag, notes, repeat rules.</p><h2 id="list-filters" tabindex="-1">List filters <a class="header-anchor" href="#list-filters" aria-label="Permalink to &quot;List filters&quot;">​</a></h2><p>Use <strong>sidebar list chips</strong> to focus on one list (including Inbox). Filtering hides other lists from task views and can affect what you see on the calendar sidebar context.</p><h2 id="subtasks-advanced" tabindex="-1">Subtasks (advanced) <a class="header-anchor" href="#subtasks-advanced" aria-label="Permalink to &quot;Subtasks (advanced)&quot;">​</a></h2><p>Off by default. Turn on <strong>Subtasks (advanced)</strong> under <strong>Settings → Scheduler</strong> to break a parent task into ordered steps.</p><ul><li>Add subtasks on a <strong>parent</strong> task in the editor (title and duration per step).</li><li>Only the <strong>parent</strong> is auto-scheduled; subtasks inherit list and scheduling hours and do not schedule on their own.</li><li>Parent <strong>duration</strong> is the rollup of incomplete subtask durations (read-only while subtasks exist).</li><li>On the <strong>calendar</strong>, one block represents the parent; subtasks appear as <strong>stacked segments</strong> inside that block (proportional to each step’s duration). Click a segment to open that subtask; click the parent chrome to edit the parent.</li><li>In <strong>list</strong> layout, expand a parent row to see nested subtasks; a <strong>2/5</strong> badge shows completion progress.</li><li>Completing all subtasks marks the parent complete; completing the parent completes all subtasks.</li><li>With the setting off, subtasks stay in your data but are hidden from task lists until you turn the feature back on.</li></ul><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><p>Link tasks so one must finish before another starts. The scheduler uses a topological sort; cycles are rejected.</p><p><strong>Dependency drag direction</strong> (Settings): controls whether dragging a link means “target depends on dragged” or the reverse — match your mental model and stick to one setting.</p><h2 id="completion-and-auto-schedule" tabindex="-1">Completion and auto-schedule <a class="header-anchor" href="#completion-and-auto-schedule" aria-label="Permalink to &quot;Completion and auto-schedule&quot;">​</a></h2><p>Completing a task removes it from scheduling. Editing due date, duration, list hours profile, or dependencies triggers a reschedule pass (same as adding/deleting tasks).</p><p>See <a href="./calendar">Calendar</a> for placement and lock behavior after tasks are scheduled.</p>',40)])])}const y=s(g,[["render",h]]);export{w as __pageData,y as default};
